$db=Database::connect();$meta=json_decode(file_get_contents($argv[1]),true);$creds=json_decode(file_get_contents($argv[2]),true);$a=$meta['merchants']['a'];$b=$meta['merchants']['b'];$r=['passed'=>0,'failed'=>0,'cases'=>[]];
function ok(bool $v):void{if(!$v)throw new RuntimeException('Assertion failed');}function deny(callable $f):void{try{$f();}catch(DomainException|InvalidArgumentException|PDOException){return;}throw new RuntimeException('Expected denial');}function test(string $n,callable $f):void{global$r;try{$f();$r['passed']++;$r['cases'][$n]='PASS';}catch(Throwable $e){$r['failed']++;$r['cases'][$n]=get_class($e).':'.$e->getMessage().' at '.basename($e->getFile()).':'.$e->getLine();}}function keyid():string{return bin2hex(random_bytes(16));}
function auth(array $m,string $name,string $password):StaffSessionIdentity{global$db;$q=$db->prepare('SELECT outlet_code FROM outlets WHERE outlet_id=?');$q->execute([$m['loginOutlet']]);$native=(new StaffAccountService($db,$q->fetchColumn(),getenv('KIOS_MERCHANT_AUTH_RATE_KEY')))->authenticate($name,$password,'m06a-synthetic');ok($native!==null);$s=[];StaffAccountService::bind($s,$native);$s['_merchant_login_outlet']=$m['loginOutlet'];return new StaffSessionIdentity($db,static fn()=>$s,getenv('KIOS_MERCHANT_AUTH_RATE_KEY'));}
$platform=auth($meta['platform'],$creds['platform_username'],$creds['platform_password']);$owner=auth($a,$a['username'],$creds['owner_a_password']);$other=auth($b,$b['username'],$creds['owner_b_password']);putenv('KIOS_ENTITLEMENTS_ENABLED=1');$e=new Entitlements($db,$platform);
if(($argv[4]??'')==='worker'){try{echo json_encode($e->assign($argv[5],$argv[6],$argv[7],'starter','1',$argv[8],$argv[9],'Concurrent synthetic assignment'));exit;}catch(Throwable $x){echo json_encode(['error'=>get_class($x),'message'=>$x->getMessage()]);exit(1);}}
function fingerprints():array{global$db;$r=[];foreach(['orders','order_items','payment_confirmations','print_jobs','merchant_inventory_items','merchant_inventory_movements','merchant_inventory_events','merchant_seating_tables','merchant_seating_reservations','merchant_service_sessions','merchant_bill_drafts','merchant_bill_revisions']as$t){$rows=$db->query('SELECT * FROM '.$t.' ORDER BY 1')->fetchAll(PDO::FETCH_ASSOC);$r[$t]=hash('sha256',serialize($rows));}return$r;}$before=fingerprints();$features=Entitlements::FEATURES;$limits=['outlets'=>'20','products'=>'1000','staff'=>'100','tables'=>'100'];$start=gmdate('Y-m-d\TH:i',time()-60);$end=gmdate('Y-m-d\TH:i',time()+365*86400);
$c=null;$cAuth=null;$growth=array_values(array_diff($features,['analytics','multi_outlet']));
test('Native platform only plan creation; strict field features limits and dependency validation',function()use($e,$owner,$features,$limits){deny(fn()=>(new Entitlements($GLOBALS['db'],$owner))->plan(keyid(),'illegal','0','Illegal','Not authorized',[],$limits,'1'));deny(fn()=>$e->plan(keyid(),'invalid','0','Invalid','Invalid unknown feature',['unknown'],$limits,'1'));deny(fn()=>$e->plan(keyid(),'invalid','0','Invalid','Recipe prerequisites missing',['recipes'],$limits,'1'));$e->plan(keyid(),'enterprise','0','Enterprise','Illustrative full synthetic demonstration',$features,$limits,'1');});
test('Plan versions immutable; idempotency stale edits and inactive assignment policy',function()use($e,$growth,$limits,$db){$key=keyid();$p=$e->plan($key,'growth','0','Growth','Illustrative operations plan',$growth,$limits,'1');ok($e->plan($key,'growth','0','Growth','Illustrative operations plan',$growth,$limits,'1')===$p);deny(fn()=>$e->plan(keyid(),'growth','0','Growth','Stale edit',$growth,$limits,'1'));deny(fn()=>$db->exec("UPDATE merchant_plan_versions SET name='Override'"));deny(fn()=>$db->exec('DELETE FROM merchant_plan_versions'));$e->plan(keyid(),'starter','0','Starter','Illustrative small menu and branding',['menu','branding'],['outlets'=>'1','products'=>'1','staff'=>'1','tables'=>'1'],'1');});
test('Third independent merchant is provisioned through existing internal workflow',function()use($db,$platform,&$c,&$cAuth,&$meta,&$creds){putenv('KIOS_ENTITLEMENTS_ENABLED=0');try{$p=new MerchantProvisioner($db,$platform);$receipt=$p->provision(keyid(),['business_name'=>'Synthetic Restaurant C','business_type'=>'restaurant','admin_contact'=>'owner-c@example.test','outlet_name'=>'Synthetic Outlet C','owner_name'=>'Synthetic owner C','owner_username'=>'m06a-owner-c','opening_time'=>'08:00','closing_time'=>'22:00'])['receipt'];$pw='Synthetic-M06A-C-password-123';$receipt=$p->activate($receipt['merchant_id'],1,keyid(),$pw,$pw)['receipt'];$c=['merchant'=>$receipt['merchant_id'],'outlet'=>$receipt['merchant_outlet_id'],'loginOutlet'=>(int)$receipt['legacy_outlet_id'],'username'=>'m06a-owner-c'];$cAuth=auth($c,$c['username'],$pw);$meta['merchants']['c']=$c;$creds['owner_c_username']=$c['username'];$creds['owner_c_password']=$pw;file_put_contents($GLOBALS['argv'][1],json_encode($meta));file_put_contents($GLOBALS['argv'][2],json_encode($creds));}finally{putenv('KIOS_ENTITLEMENTS_ENABLED=1');}});
test('Three merchants receive independent Enterprise Growth Starter assignments',function()use($e,$a,$b,&$c,$start,$end){deny(fn()=>$e->assign(keyid(),$a['merchant'],'0','starter','1',$start,$end,'Unsafe first assignment for existing work'));foreach([[$a,'enterprise'],[$b,'growth'],[$c,'starter']]as[$m,$plan])$e->assign(keyid(),$m['merchant'],'0',$plan,'1',$start,$end,'Synthetic initial plan');});
test('Tenant outlet isolation and owner upgrade rejection remain enforced',function()use($db,$owner,$a,$b,&$c,$start,$end){$x=new Entitlements($db,$owner);deny(fn()=>$x->overview($b['merchant'],$b['outlet']));deny(fn()=>$x->requireFeature($a['merchant'],$b['outlet'],'menu'));deny(fn()=>$x->assign(keyid(),$a['merchant'],'1','enterprise','1',$start,$end,'Unauthorized owner escalation'));});
test('Direct service and report APIs deny unlicensed modules',function()use($db,$other,$b,&$c,&$cAuth){deny(fn()=>(new OperationalAnalytics($db,$other))->load($b['merchant'],$b['outlet'],gmdate('Y-m-d'),gmdate('Y-m-d')));deny(fn()=>(new Inventory($db,$cAuth))->load($c['merchant'],$c['outlet']));deny(fn()=>(new BillDrafts($db,$cAuth))->load($c['merchant'],$c['outlet']));deny(fn()=>(new StaffPos($db,$cAuth))->load($c['merchant'],$c['outlet']));});
