test('Expired assignment fails closed while preserving original history',function()use($db,&$c,&$cAuth){$future=new Entitlements($db,$cAuth,static fn()=>time()+366*86400);ok($future->overview($c['merchant'],$c['outlet'])['state']==='EXPIRED');deny(fn()=>$future->requireFeature($c['merchant'],$c['outlet'],'menu'));ok(count($future->overview($c['merchant'],$c['outlet'])['history'])===1);});
