test('Expired operational entitlement denies new work but preserves scoped completion admission',function()use($db,$owner,$a){$future=new Entitlements($db,$owner,static fn()=>time()+366*86400);deny(fn()=>$future->requireFeature($a['merchant'],$a['outlet'],'pos'));$future->requireFeature($a['merchant'],$a['outlet'],'pos','drain-read');$future->requireFeature($a['merchant'],$a['outlet'],'kitchen','drain');deny(fn()=>$future->requireFeature($a['merchant'],$a['outlet'],'billing'));});
