test('Actual concurrent duplicate assignment commits exactly one immutable revision',function()use($e,$argv,&$c,$start,$end,&$r){$key=keyid();$children=[];for($i=0;$i<2;$i++){$pipes=[];$p=proc_open([PHP_BINARY,__FILE__,$argv[1],$argv[2],$argv[3],'worker',$key,$c['merchant'],'3',$start,$end],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);ok(is_resource($p));fclose($pipes[0]);$children[]=[$p,$pipes];}$results=[];foreach($children as[$p,$pipes]){$o=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($p);$r['workers'][]=['exit'=>$exit,'response'=>$o,'stderr'=>$err];ok($exit===0);$results[]=json_decode($o,true);}ok($results[0]===$results[1]);ok($results[0]['version']===4);});
test('Assignment audit failure rolls back head version and no misleading success record',function()use($e,$db,&$c,$start,$end){$db->exec("CREATE TRIGGER subscription_test_failure BEFORE INSERT ON merchant_plan_assignments FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic audit outage'");try{deny(fn()=>$e->assign(keyid(),$c['merchant'],'4','starter','1',$start,$end,'Synthetic rollback test'));$q=$db->prepare('SELECT version FROM merchant_plan_heads WHERE merchant_id=?');$q->execute([$c['merchant']]);ok((int)$q->fetchColumn()===4);}finally{$db->exec('DROP TRIGGER subscription_test_failure');}});
